// Bundled Noto emoji renderer: every player sees identical artwork instead of whatever
// their OS font draws. Art lives in /public/emoji, generated by scripts/fetch-noto-emoji.mjs
// (animated Noto is CC BY 4.0 — credited in the marketing footer and LICENSES/NOTO.md).
//
// Two weights, on purpose: the default is the original static Noto (flat SVG, a few KB) for pickers,
// store and history; `animated` swaps in the 160px animated WebP and is for the moment a reaction
// is actually thrown or lands. Glyphs Google never animated ship that one SVG for both. The flat
// cucumber is the sliced one, so it keeps a frame of the animation (whole) as its still.
// A glyph outside the manifest falls back to the raw character.
import Image from 'next/image';
import {useState} from 'react';
import {NOTO_EMOJI} from './emojiManifest';

export function codepointFor(glyph: string) {
  return Array.from(glyph).map(char => char.codePointAt(0)!.toString(16)).join('-');
}

export function emojiSrc(glyph: string, animated = false) {
  const codepoint = codepointFor(glyph);
  const kind = NOTO_EMOJI[codepoint];
  if (!kind) return undefined;
  if (kind === 'svg') return `/emoji/${codepoint}.svg`;
  if (animated) return `/emoji/${codepoint}.webp`;
  return kind === 'anim' ? `/emoji/${codepoint}.svg` : `/emoji/${codepoint}-still.webp`;
}

export function EmojiGlyph({glyph, animated = false}: { glyph: string; animated?: boolean }) {
  // Reduced motion never plays the animation: the still is the same art, frame 0.
  const [reduced] = useState(() => typeof window !== 'undefined'
    && !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches);
  const src = emojiSrc(glyph, animated && !reduced);
  return src
    ? <Image className="emoji-glyph" src={src} unoptimized alt="" aria-hidden="true" width={20} height={20}/>
    : <span aria-hidden="true">{glyph}</span>;
}
